def print_a(n):
    for i in range(n):
        print('A', end=' ')
    print()

# Example usage:
print_a(1)

def print_a(n):
    for i, x in enumerate(range(n)):
        print('A', end=' ')
    print()

# Example usage:
print_a(1)

